def _parse(v):
    """Obviously-correct reference parsing per spec: ',' is decimal point."""
    if isinstance(v, str):
        return float(v.replace(",", "."))
    return float(v)

def _expected(a, b):
    na = _parse(a)
    nb = _parse(b)
    if na == nb:
        return None
    return a if na > nb else b

def _decimal_string(draw, use_comma):
    neg = draw(st.booleans())
    ip = draw(st.integers(min_value=0, max_value=1000))
    fp = draw(st.integers(min_value=0, max_value=999))
    # ensure at least one fractional digit; pad to keep it simple
    s = f"{ip}.{fp:03d}"
    if use_comma:
        s = s.replace(".", ",")
    if neg:
        s = "-" + s
    return s

def numeric_values(draw):
    kind = draw(st.integers(min_value=0, max_value=3))
    if kind == 0:
        return draw(ints)
    if kind == 1:
        return draw(finite_floats)
    if kind == 2:
        # dot string
        return _decimal_string(draw, False)
    else:
        # comma string
        return _decimal_string(draw, True)

def numeric_pairs(draw):
    return (draw(numeric_values), draw(numeric_values))

@given(numeric_pairs)
def test_property_matches_reference_model(pair):
    a, b = pair
    got = compare_one(a, b)
    exp = _expected(a, b)
    if exp is None:
        assert got is None
    else:
        assert got is (a if exp is a else b)
        assert type(got) is type(exp)
        assert got == exp
